import { Host, h } from "@stencil/core";
import FlashIcon from "../../assets/svg/flash.svg";
/**
 * Backend eligibility flag (Store-Module StoreSettingsAction, PR #1627), nested under the
 * store settings `shipping` attribute. True only when the store is on Pro, Quick Delivery
 * (bullet-delivery) is accessible for customers, and the request carries a resolved scope
 * allocation (the branch resolved during the login-cycle).
 */
const ELIGIBILITY_FLAG_KEY = 'store.shipping.has_bullet_delivery_tag';
/**
 * @name SallaBulletDeliveryTag
 * @description Fixed "Quick Delivery" tag for the storefront homepage header
 *   (e.g. "توصيل خلال ساعتين" / "Delivery within 2 hours").
 *
 *   Eligibility is decided entirely by the backend and delivered as a single
 *   boolean, `store.shipping.has_bullet_delivery_tag` (Store-Module
 *   `StoreSettingsAction::isQuickDeliveryEligible`). The backend sets it true only
 *   when the store is on Pro, Quick Delivery (`bullet-delivery`) is accessible for
 *   customers, and the request already carries a resolved scope allocation (the
 *   branch resolved during the login-cycle). The flag is recomputed per branch and
 *   re-injected on each page load — including after the login-cycle reload — so the
 *   tag re-evaluates naturally without a client-side eligibility gate.
 *
 *   Read-only: no network request; renders nothing when not eligible (fail-safe —
 *   never a broken/half tag, no layout shift).
 * @tag salla-bullet-delivery-tag
 */
export class SallaBulletDeliveryTag {
    constructor() {
        /** Mirrors the backend `has_bullet_delivery_tag` flag; drives whether the tag renders. */
        this.isEligible = false;
    }
    async componentWillLoad() {
        try {
            await salla.onReady();
            await salla.lang.onLoaded();
            this.isEligible = salla.config.get(ELIGIBILITY_FLAG_KEY) === true;
        }
        catch (e) {
            // Any read/await failure → stay hidden (fail-safe).
            salla?.logger?.warn?.('salla-bullet-delivery-tag: init failed', e);
            this.isEligible = false;
        }
    }
    /** Fixed tag copy. Localized via lang key when present, otherwise a language-aware default. */
    getTagLabel() {
        const fallback = salla.config.get('user.language_code') === 'en'
            ? 'Get it within 2 hours'
            : 'توصيل خلال ساعتين';
        return salla.lang.getWithDefault('pages.products.quick_delivery_tag', fallback);
    }
    render() {
        if (!this.isEligible) {
            return null;
        }
        return (h(Host, { class: "s-bullet-delivery-tag-wrapper" }, h("span", { class: "s-bullet-delivery-tag-container", "data-testid": "bd-tag" }, h("span", { class: "s-bullet-delivery-tag-icon", innerHTML: FlashIcon }), h("span", { class: "s-bullet-delivery-tag-label" }, this.getTagLabel()))));
    }
    static get is() { return "salla-bullet-delivery-tag"; }
    static get originalStyleUrls() {
        return {
            "$": ["salla-bullet-delivery-tag.scss"]
        };
    }
    static get styleUrls() {
        return {
            "$": ["salla-bullet-delivery-tag.css"]
        };
    }
    static get states() {
        return {
            "isEligible": {}
        };
    }
}
